CREATE TABLE IF NOT EXISTS "__DataProtectionMigrations" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___DataProtectionMigrations" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__DataProtectionMigrations" WHERE "MigrationId" = '20261031134534_PersistDataProtectionKeys') THEN
    CREATE TABLE "DataProtectionKeys" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "FriendlyName" text,
        "Xml" text,
        CONSTRAINT "PK_DataProtectionKeys" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__DataProtectionMigrations" WHERE "MigrationId" = '20261031134534_PersistDataProtectionKeys') THEN
    INSERT INTO "__DataProtectionMigrations" ("MigrationId", "ProductVersion")
    VALUES ('20261031134534_PersistDataProtectionKeys', '10.0.13');
    END IF;
END $EF$;
COMMIT;

